{
  "status": "SUPPORTED",
  "task_summary": "The task requires identifying fastening components from storage, performing a fastening operation on a workpiece, and placing the tool back on the workbench. The scene contains a workbench with a workpiece, and storage structures (cabinet, drawers) where tools/components may be located.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to secure the component to the workpiece.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "wrench", "pliers"],
        "required_properties": ["grasping capability", "force application"]
      },
      {
        "id": "component",
        "entity_kind": "OBJECT",
        "function": "A part compatible with the workpiece that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["screw", "nut", "bolt", "pin"],
        "required_properties": ["threaded", "fitting shape"]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The object receiving the fastening.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["assembly", "fixture", "block"],
        "required_properties": ["receptacle", "mounting points"]
      },
      {
        "id": "storage_structure",
        "entity_kind": "REGION",
        "function": "Enclosed space containing tools or components to be searched.",
        "required_count": 3,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["cabinet", "drawer", "compartment"],
        "required_properties": ["enclosed", "openable"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the fastening occurs and where the tool is placed.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table", "bench", "surface"],
        "required_properties": ["flat", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "fits",
        "relation": "component fits workpiece",
        "participant_roles": [
          "component",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "operates_on",
        "relation": "fastening_tool operates on component and workpiece",
        "participant_roles": [
          "fastening_tool",
          "component",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "placed_on",
        "relation": "fastening_tool placed on workbench",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_identify",
        "operation": "Search storage structures to find component and fastening_tool",
        "participant_roles": [
          "storage_structure",
          "fastening_tool",
          "component"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "Apply fastening_tool to attach component to workpiece",
        "participant_roles": [
          "fastening_tool",
          "component",
          "workpiece",
          "workbench"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "place_equipment",
        "operation": "Place fastening_tool on workbench",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  }
,
